select case when products.price >= 1300 then 'high' when products.price >= 480 then 'mid' else 'low' end as price_bucket, avg(order_items.unit_price) as avg_unit_price, max(order_items.unit_price) as max_unit_price from order_items left join products on order_items.product_id = products.id group by case when products.price >= 1300 then 'high' when products.price >= 480 then 'mid' else 'low' end;
